    async loadCustomers(bucket: string): Promise<Array<CustomerRecord>> {
        const keys = await listDocuments(bucket, this.customerRecordPrefix);
        const records = await Promise.all(keys.map((key) => getDocument<CustomerRecord>(bucket, key)));
